export const STEPS = STEPS_5STAR;

/** Step index where 5★ main path meets the steer_to_5_then_1 overlap (e.g. "but"). */
export const BRANCH_FROM_5_INDEX = 6;

/** Step index where 1★ main path meets the steer_to_1_then_5 overlap (e.g. "at"). */
export const BRANCH_FROM_1_INDEX = 5;

/** Labels for prompt-only steps (I, really) on the chart. */
export const CHART_PREFIX_LABELS = ["I","really"];

/** Shown in grey before steered decode; generation is appended after this. Override with `fixed_prompt_display` on `steps[0]`. */
export const FIXED_STEER_PROMPT_DISPLAY = '[sos] I really ';

export function getFixedSteerPromptDisplay(steps) {
  if (steps?.length && typeof steps[0].fixed_prompt_display === 'string')
    return steps[0].fixed_prompt_display;
  return FIXED_STEER_PROMPT_DISPLAY;
}

export function countPromptOnlySteps(steps) {
  if (!steps?.length) return 0;
  let n = 0;
  for (const s of steps) {
    if (s.prompt_only) n++;
    else break;
  }
  return n;
}

export function mergeTraceAtBranch(mainSteps, branchSteps, branchIndex) {
  return [...mainSteps.slice(0, branchIndex), ...branchSteps.slice(branchIndex)];
}
